import math

def kernel(x):
 x=abs(x)
 if x<1e-10:return 1.0
 if x>=3:return 0.0
 return math.sin(math.pi*x)/(math.pi*x)*math.sin(math.pi*x/3)/(math.pi*x/3)
def weights(old,new):
 out=[]
 scale=old/new
 for i in range(new):
  center=(i+.5)*scale-.5
  fw=max(scale,1)
  lo=max(0,math.ceil(center-3*fw))
  hi=min(old-1,math.floor(center+3*fw))
  ws=[(x,kernel((x-center)/fw)) for x in range(lo,hi+1)]
  total=sum(v for x,v in ws)
  out.append([(x,v/total) for x,v in ws])
 return out
def u8(x):return min(255,max(0,math.floor(x+.5)))
def resize(ps,w,h,nw,nh):
 def calc(inp,ws):
  a=sum(inp[x][3]*v for x,v in ws)
  if a<=0:return (0,0,0,0)
  cs=[u8(sum(inp[x][j]*inp[x][3]*v for x,v in ws)/a) for j in range(3)]
  return tuple(cs+[u8(a)])
 if w!=nw:
  ws=weights(w,nw)
  ps=[calc(ps[y*w:(y+1)*w],wx) for y in range(h) for wx in ws]
 if h!=nh:
  ws=weights(h,nh)
  ps=[calc(ps[x::nw],wy) for wy in ws for x in range(nw)]
 return ps
