// Package raster implements pixel storage, alpha-aware resampling, and framing.
package raster

import (
    "image"
    "image/color"
    "math"
)

type Pixel struct { R, G, B, A uint8 }
type Image struct {
    W, H int
    Pix []Pixel
}
func New(w,h int) *Image {
    if w<0 { w=0 }; if h<0 { h=0 }
    return &Image{W:w,H:h,Pix:make([]Pixel,w*h)}
}
func FromImage(src image.Image) *Image {
    b:=src.Bounds()
    out:=New(b.Dx(),b.Dy())
    for y:=0;y<out.H;y++ {
        for x:=0;x<out.W;x++ {
            p:=color.NRGBAModel.Convert(src.At(b.Min.X+x,b.Min.Y+y)).(color.NRGBA)
            out.Pix[y*out.W+x]=Pixel{p.R,p.G,p.B,p.A}
        }
    }
    return out
}
func Byte(v float64) uint8 {
    if v<=0 { return 0 }; if v>=255 { return 255 }
    return uint8(v+0.5)
}
type weight struct { at int; value float64 }
func lanczos(v float64) float64 {
    v=math.Abs(v)
    if v==0 { return 1 }
    if v>=3 { return 0 }
    p:=math.Pi*v
    return (math.Sin(p)/p)*(math.Sin(p/3)/(p/3))
}
func coefficients(old,n int) [][]weight {
    out:=make([][]weight,n)
    ratio:=float64(old)/float64(n)
    scale:=math.Max(ratio,1)
    for i:=range out {
        center:=(float64(i)+0.5)*ratio-0.5
        lo:=int(math.Ceil(center-3*scale)); if lo<0 {lo=0}
        hi:=int(math.Floor(center+3*scale)); if hi>=old {hi=old-1}
        total:=0.0
        for j:=lo;j<=hi;j++ {
            v:=lanczos((float64(j)-center)/scale)
            if v==0 { continue }
            out[i]=append(out[i],weight{j,v})
            total+=v
        }
        if total!=0 { for j:=range out[i] {out[i][j].value/=total} }
    }
    return out
}
func weighted(src *Image, base,stride int, ws []weight) Pixel {
    var r,g,b,a float64
    for _,w:=range ws {
        p:=src.Pix[base+w.at*stride]
        aw:=float64(p.A)*w.value
        r+=float64(p.R)*aw
        g+=float64(p.G)*aw
        b+=float64(p.B)*aw
        a+=aw
    }
    if a<=0 {return Pixel{}}
    return Pixel{Byte(r/a),Byte(g/a),Byte(b/a),Byte(a)}
}
func Resize(src *Image,w,h int) *Image {
    if w<0 || h<0 || (w==0 && h==0) || src.W==0 || src.H==0 {return New(0,0)}
    if w==0 { w=int(math.Max(1,math.Floor(float64(h)*float64(src.W)/float64(src.H)+0.5))) }
    if h==0 { h=int(math.Max(1,math.Floor(float64(w)*float64(src.H)/float64(src.W)+0.5))) }
    if src.W!=w {
        out:=New(w,src.H)
        weights:=coefficients(src.W,w)
        for y:=0;y<src.H;y++ {for x:=0;x<w;x++ {out.Pix[y*w+x]=weighted(src,y*src.W,1,weights[x])}}
        src=out
    }
    if src.H!=h {
        out:=New(w,h)
        weights:=coefficients(src.H,h)
        for y:=0;y<h;y++ {for x:=0;x<w;x++ {out.Pix[y*w+x]=weighted(src,x,w,weights[y])}}
        src=out
    }
    return src
}
func Crop(src *Image,x,y,w,h int) *Image {
    out:=New(w,h)
    for j:=0;j<h;j++ { for i:=0;i<w;i++ {
        if i+x>=0 && i+x<src.W && j+y>=0 && j+y<src.H {out.Pix[j*w+i]=src.Pix[(j+y)*src.W+i+x]}
    }}
    return out
}
func Fit(src *Image,w,h int) *Image {
    if w<=0 || h<=0 { return New(0,0) }
    if src.W<=w && src.H<=h {return src}
    ratio:=math.Min(float64(w)/float64(src.W),float64(h)/float64(src.H))
    nw:=int(float64(src.W)*ratio+0.5);nh:=int(float64(src.H)*ratio+0.5)
    if nw<1 {nw=1};if nh<1 {nh=1}
    return Resize(src,nw,nh)
}
func Fill(src *Image,w,h int) *Image {
    if w<=0 || h<=0 {return New(0,0)}
    ratio:=math.Max(float64(w)/float64(src.W),float64(h)/float64(src.H))
    nw:=int(float64(src.W)*ratio+0.5);nh:=int(float64(src.H)*ratio+0.5)
    if nw<w {nw=w};if nh<h {nh=h}
    scaled:=Resize(src,nw,nh)
    return Crop(scaled,(nw-w)/2,(nh-h)/2,w,h)
}
// Composite converts non-premultiplied pixels over an opaque matte. The
