            v:=data[at];at++
            for i:=0;i<1-n;i++ {out=append(out,v)}
        }
    }
    return out,nil
}

// TIFF LZW is MSB-first, with a clear code and the early code-width change.
func tiffLZW(data []byte) ([]byte,error) {
    table:=make([][]byte,4096)
    for i:=0;i<256;i++ {table[i]=[]byte{byte(i)}}
