package raster

import (
    "bytes"
    "encoding/binary"
    "image"
    "image/color"
    "image/png"
    "reflect"
    "testing"
)

func TestAlphaComposite(t *testing.T) {
    src:=&Image{W:1,H:1,Pix:[]Pixel{{255,63,127,128}}}
    for _,test:=range []struct{matte Pixel;want Pixel}{
        {Pixel{A:255},Pixel{128,31,63,255}},
        {Pixel{255,255,255,255},Pixel{255,159,191,255}},
        {Pixel{171,205,239,255},Pixel{213,134,183,255}},
    } {
        if p:=Composite(src,test.matte).Pix[0];p!=test.want {t.Errorf("composite = %#v; want %#v",p,test.want)}
    }
}
func TestResizeAndFraming(t *testing.T) {
    src:=&Image{W:1,H:2,Pix:[]Pixel{{255,0,0,255},{0,0,255,255}}}
    got:=Resize(src,1,6)
    want:=[]Pixel{{255,0,0,255},{255,0,0,255},{173,0,82,255},{82,0,173,255},{0,0,255,255},{0,0,255,255}}
    if !reflect.DeepEqual(got.Pix,want) {t.Fatalf("resized: %#v",got.Pix)}
    for _,dims:=range [][4]int{{1440,900,13,8},{8,24,5,16},{3,5,3,5}} {
        fit:=Fit(New(dims[0],dims[1]),13,16)
        if fit.W!=dims[2] || fit.H!=dims[3] {t.Errorf("fit %dx%d: %dx%d",dims[0],dims[1],fit.W,fit.H)}
    }
    if f:=Fill(src,4,8);f.W!=4 || f.H!=8 {t.Fatalf("fill: %dx%d",f.W,f.H)}
}
func TestPNG(t *testing.T) {
    im:=image.NewNRGBA64(image.Rect(0,0,2,2))
    im.SetNRGBA64(0,0,color.NRGBA64{R:65535,G:257,B:32896,A:12850})
    im.SetNRGBA64(1,0,color.NRGBA64{R:65535,A:65535})
    var b bytes.Buffer
    if err:=png.Encode(&b,im);err!=nil {t.Fatal(err)}
    decoded,err:=Decode(b.Bytes())
    if err!=nil {t.Fatal(err)}
    if decoded.W!=2 || decoded.H!=2 || decoded.Pix[0]!=(Pixel{255,1,128,50}) {t.Fatalf("PNG decode: %#v",decoded)}
}
func TestBMP(t *testing.T) {
    data:=make([]byte,70)
    data[0],data[1]='B','M'
    le:=binary.LittleEndian
    le.PutUint32(data[2:],uint32(len(data)))
    le.PutUint32(data[10:],54);le.PutUint32(data[14:],40)
    le.PutUint32(data[18:],2);le.PutUint32(data[22:],2)
    le.PutUint16(data[26:],1);le.PutUint16(data[28:],24)
    copy(data[54:],[]byte{255,0,0,255,255,255,0,0,0,0,255,0,255,0,0,0})
    decoded,err:=Decode(data)
    if err!=nil {t.Fatal(err)}
    want:=[]Pixel{{255,0,0,255},{0,255,0,255},{0,0,255,255},{255,255,255,255}}
    if !reflect.DeepEqual(decoded.Pix,want) {t.Fatalf("BMP pixels: %#v",decoded.Pix)}
    le.PutUint32(data[10:],55)
    if _,err:=Decode(data);err==nil || err.Error()!="bmp: unsupported BMP image" {t.Fatalf("BMP offset: %v",err)}
}
func TestTIFFCompressionPrimitives(t *testing.T) {
    got,err:=unpackBits([]byte{2,'a','b','c',254,'x',128,0,'z'})
    if err!=nil || string(got)!="abcxxxz" {t.Fatalf("PackBits: %q %v",got,err)}
    var coded []byte
    value,bits:=uint64(0),0
    for _,v:=range []int{256,65,66,258,257} {
        value=(value<<9)|uint64(v);bits+=9
        for bits>=8 {bits-=8;coded=append(coded,byte(value>>bits))}
    }
    if bits>0 {coded=append(coded,byte(value<<uint(8-bits)))}
    got,err=tiffLZW(coded)
    if err!=nil || string(got)!="ABAB" {t.Fatalf("LZW: %q %v",got,err)}
}
func TestTIFF(t *testing.T) {
    tags:=[][3]uint32{
        {256,4,2},{257,4,2},{258,3,8},{259,3,1},{262,3,1},
        {273,4,134},{277,3,1},{278,4,2},{279,4,4},{284,3,1},
    }
    data:=make([]byte,138)
    copy(data,"II*\x00")
    le:=binary.LittleEndian;le.PutUint32(data[4:],8);le.PutUint16(data[8:],uint16(len(tags)))
    for i,tag:=range tags {
        at:=10+i*12
        le.PutUint16(data[at:],uint16(tag[0]));le.PutUint16(data[at+2:],uint16(tag[1]))
        le.PutUint32(data[at+4:],1);le.PutUint32(data[at+8:],tag[2])
    }
    copy(data[134:],[]byte{0,100,200,255})
    got,err:=Decode(data)
    if err!=nil {t.Fatal(err)}
    for i,v:=range []uint8{0,100,200,255} {if p:=got.Pix[i];p!=(Pixel{v,v,v,255}) {t.Errorf("TIFF pixel %d = %#v",i,p)}}
}
